from PIL import ImageFilter
for med in [9,17,25,31]:
 sm=np.asarray(Image.fromarray(labels).filter(ImageFilter.MedianFilter(med)))
 for step in [20,25,30,35,40,45,50]:
  total_nodes=0; total_comp=0; bylabel=[]
  for c in range(16):
   nodes=[]
   for j,x in enumerate(range(20,1024,step)):
    col=sm[:,x]==c
    starts=np.where(col & ~np.r_[False,col[:-1]])[0]
    ends=np.where(col & ~np.r_[col[1:],False])[0]
    nodes.extend((j,int(a),int(b)) for a,b in zip(starts,ends))
   n=len(nodes); p=list(range(n))
   def f(x):
    while p[x]!=x: p[x]=p[p[x]]; x=p[x]
    return x
   # connect any same or adjacent lanes with vertical intervals overlap or gap<=step
   lane_nodes={}
   for i,(j,a,b) in enumerate(nodes):lane_nodes.setdefault(j,[]).append((i,a,b))
   for j,aa in lane_nodes.items():
    for i,a,b in aa:
     for h,cc,d in lane_nodes.get(j+1,[]):
      if min(b,d)+step>=max(a,cc):
       x,y=f(i),f(h)
       if x!=y:p[x]=y
   ncomp=len(set(f(i) for i in range(n)))
   total_nodes+=n;total_comp+=ncomp;bylabel.append(ncomp)
  print('med',med,'step',step,'nodes',total_nodes,'comp',total_comp,'lab',bylabel)
